import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.inventoryLocations().listInventoryLocations(Map.of("q", "Sydney"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("inventory_locations")) {
    Map<?, ?> location = (Map<?, ?>) row;
    System.out.println(location.get("id") + " " + location.get("name") + " " + location.get("default"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

